     expect(executorInputs).toEqual([{location: 'Paris', unit: 'celsius'}]);
   });
+
+  it('compiles a static schema once at register time and reuses the validator across ten execute calls', async () => {
+    const registry = new ToolRegistry();
+    let schemaReads = 0;
+    const schemaTarget: Record<string, unknown> = {
+      type: 'object',
+      properties: {location: {type: 'string'}},
+      required: ['location'],
+    };
+    const inputSchema: Record<string, unknown> = new Proxy(schemaTarget, {
+      get: (target, property) => {
+        if (typeof property === 'string') schemaReads += 1;
+        return Reflect.get(target, property);
+      },
+    });
+    registry.register(
