+      async () => 'sunny'
+    );
+
+    const readsAtRegister = schemaReads;
+    let result = '';
+    for (let call = 0; call < 10; call++) {
+      result = (await registry.execute('get_weather', {location: 'Paris'})).result;
+    }
+
